report={'status':'native manufacturer-distance screen; not fabrication release','date':'2026-11-02','kicad':'10.0.8','input_sha256':{f.relative_to(P).as_posix():sha(f) for f in [D/'screen.kicad_pcb',D/'screen.kicad_pro',D/'screen.kicad_dru',D/'positive-control.kicad_dru',D/'drc-all-layers.json',D/'positive-control.json']},'frozen_pcb_sha256':sha(B/'naehe-glut-r2b.kicad_pcb'),'copy_byte_identical':sha(D/'screen.kicad_pcb')==sha(B/'naehe-glut-r2b.kicad_pcb'),'tests':[{'item':'PTH foreign-copper clearance','layers':'all; inner rule overrides','threshold_mm':0.28,'inner_threshold_mm':0.30},{'item':'Via foreign-copper clearance','layers':'all six copper layers','threshold_mm':0.20}],'new_rule_violations':len(new),'known_npth_violations':sum(v['type']=='hole_clearance' for v in r['violations']),'unconnected':len(r['unconnected_items']),'positive_control':{'inner_pth_threshold_mm':3.0,'rule_triggered_count':len(positive),'reported_gaps_mm':sorted(set(float(re.search(r'tatsächlich ([0-9,]+)',v['description'])[1].replace(',','.')) for v in positive if re.search(r'tatsächlich ([0-9,]+)',v['description'])))},'other_violations':dict(collections.Counter(v['type'] for v in r['violations'] if v['type']!='hole_clearance')),'limitations':['109 lib_footprint_issues are missing library resolution in isolated copy, not new geometry errors and not equivalent to original two library mismatch warnings','Uses frozen zone fills; does not refill or change native geometry','hole_clearance checks foreign-net copper, not same-net copper','Does not qualify dimensional tolerances, plating, solderability, panelization or supplier CAM acceptance']}
